// Builds dist/ELISE.gs: every file in apps-script/ in one file, for pasting
// into the Apps Script editor when clasp isn't available.
// Usage: node scripts/bundle-apps-script.js   (tests/bundle.test.js checks it is current)
'use strict';
const fs = require('fs');
const path = require('path');

const ORDER = ['Code.js', 'Content.js', 'Engine.js', 'Today.js'];

function bundle() {
  const dir = path.join(__dirname, '../apps-script');
  const files = fs.readdirSync(dir).filter((f) => f.endsWith('.js'));
  const extra = files.filter((f) => !ORDER.includes(f)).sort();
  const parts = ORDER.filter((f) => files.includes(f)).concat(extra).map((f) =>
    '// ======================= ' + f + ' =======================\n' + fs.readFileSync(path.join(dir, f), 'utf8').trimEnd() + '\n');
  return '// ÉLISE — all of apps-script/ in one file. Generated by scripts/bundle-apps-script.js; do not edit.\n' +
    '// Paste into the ELISE project as Code.gs (replacing everything), with appsscript.json alongside.\n\n' +
    parts.join('\n');
}

module.exports = { bundle };
if (require.main === module) {
  fs.writeFileSync(path.join(__dirname, '../dist/ELISE.gs'), bundle());
  console.log('dist/ELISE.gs written');
}
